mapper.update:
insert into REP_CASH_YIELD(BUSI_ID, CASH_ID, CASH_NAME, CASH_TYPE, CASH_TYPE2, START_DATE, REMARK, INPUT_TYPE, INPUT_USER, STATUS, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, RATE) select BUSI_ID, CASH_ID, CASH_NAME, CASH_TYPE, CASH_TYPE2, START_DATE, REMARK, INPUT_TYPE, INPUT_USER, STATUS, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, RATE from ( select TEMP.* from (
SELECT #{item.busiId,jdbcType=VARCHAR} as BUSI_ID, #{item.cashId,jdbcType=VARCHAR} as CASH_ID, #{item.cashName,jdbcType=VARCHAR} as CASH_NAME, #{item.cashType,jdbcType=VARCHAR} as CASH_TYPE, #{item.cashType2,jdbcType=VARCHAR} as CASH_TYPE2, #{item.startDate,jdbcType=DATE} as START_DATE, #{item.remark,jdbcType=VARCHAR} as REMARK, #{item.inputType,jdbcType=VARCHAR} as INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} as INPUT_USER, #{item.status,jdbcType=VARCHAR} as STATUS, #{item.adapterId,jdbcType=VARCHAR} as ADAPTER_ID, #{item.createUser,jdbcType=VARCHAR} as CREATE_USER, #{item.createDept,jdbcType=VARCHAR} as CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} as CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} as UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} as UPDATE_TIME, #{item.rate,jdbcType=DECIMAL} as RATE from dual
) TEMP where not exisits (select 1 from REP_CASH_YIELD CII where CII.BUSI_ID=TEMP.BUSI_ID and CII.CASH_TYPE2 = TEMP.CASH_TYPE2 and CII.START_DATE = TEMP.START_DATE) ) de ;
UPDATE REP_CASH_YIELD as A, ( select CASH_ID, CASH_NAME, CASH_TYPE, REMARK, INPUT_TYPE, INPUT_USER, STATUS, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, RATE from ( select TEMP.* from (
SELECT #{item.busiId,jdbcType=VARCHAR} as BUSI_ID, #{item.cashId,jdbcType=VARCHAR} as CASH_ID, #{item.cashName,jdbcType=VARCHAR} as CASH_NAME, #{item.cashType,jdbcType=VARCHAR} as CASH_TYPE, #{item.cashType2,jdbcType=VARCHAR} as CASH_TYPE2, #{item.startDate,jdbcType=DATE} as START_DATE, #{item.remark,jdbcType=VARCHAR} as REMARK, #{item.inputType,jdbcType=VARCHAR} as INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} as INPUT_USER, #{item.status,jdbcType=VARCHAR} as STATUS, #{item.adapterId,jdbcType=VARCHAR} as ADAPTER_ID, #{item.createUser,jdbcType=VARCHAR} as CREATE_USER, #{item.createDept,jdbcType=VARCHAR} as CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} as CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} as UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} as UPDATE_TIME, #{item.rate,jdbcType=DECIMAL} as RATE from dual
) TEMP ) de ) AS B set A.* = B.* where exisits (select 1 from REP_CASH_YIELD CII where CII.BUSI_ID=TEMP.BUSI_ID and CII.CASH_TYPE2 = TEMP.CASH_TYPE2 and CII.START_DATE = TEMP.START_DATE);
